using NaturalSort.Extension;
using System;
using System.Collections.Generic;
using System.Linq;

namespace MECCG_Deck_Builder
{
    public sealed class Deck
    {
        public string Title { get; set; } = "New Deck";
        public HashSet<string> IncludedSets { get; } = new(StringComparer.OrdinalIgnoreCase);

        public List<Card> Pool { get; } = [];
        public List<Card> Resources { get; } = [];
        public List<Card> Hazards { get; } = [];
        public List<Card> Sideboard { get; } = [];
        public List<Card> Sites { get; } = [];

        public List<Card> GetSection(DeckSectionType sectionType) => sectionType switch
        {
            DeckSectionType.Pool => Pool,
            DeckSectionType.Resources => Resources,
            DeckSectionType.Hazards => Hazards,
            DeckSectionType.Sideboard => Sideboard,
            DeckSectionType.Sites => Sites,
            _ => throw new ArgumentOutOfRangeException(nameof(sectionType))
        };

        public int CountCharactersInResources()
        {
            return Resources.Count(c => string.Equals(c.Primary, "Character", StringComparison.OrdinalIgnoreCase));
        }

        public void Clear()
        {
            Title = "New Deck";
            IncludedSets.Clear();
            Pool.Clear();
            Resources.Clear();
            Hazards.Clear();
            Sideboard.Clear();
            Sites.Clear();
        }

        public void SortSections()
        {
            static int CompareCards(Card a, Card b) => StringComparer.CurrentCultureIgnoreCase.WithNaturalSort().Compare(a.Name, b.Name);

            Pool.Sort(CompareCards);
            Resources.Sort(CompareCards);
            Hazards.Sort(CompareCards);
            Sideboard.Sort(CompareCards);
            Sites.Sort(CompareCards);
        }
    }
}

using System;
using System.Collections.Generic;
using System.IO;
using System.Text;

namespace MECCG_Deck_Builder
{
    public static class DeckExportService
    {
        public static void ExportToText(Deck deck, string filePath)
        {
            var sb = new StringBuilder();

            foreach (DeckSectionType sectionType in Enum.GetValues<DeckSectionType>())
            {
                sb.AppendLine(sectionType.ToString());
                sb.AppendLine();
                foreach (var card in deck.GetSection(sectionType))
                {
                    sb.AppendLine(card.Name);
                }
                sb.AppendLine();
            }

            File.WriteAllText(filePath, sb.ToString(), Encoding.UTF8);
        }

        public static void ExportToPlayMeccg(Deck deck, string filePath)
        {
            var sb = new StringBuilder();
            var ansiEncoding = Encoding.GetEncoding(1252);

            // Pool
            sb.AppendLine("####");
            sb.AppendLine("Pool");
            sb.AppendLine("####").AppendLine();
            foreach (var card in deck.Pool)
            {
                sb.AppendLine(FormatPlayMeccgCardName(card.Name));
            }
            sb.AppendLine();

            // Deck (Resources + Hazards combined)
            sb.AppendLine("####");
            sb.AppendLine("Deck");
            sb.AppendLine("####").AppendLine();
            foreach (var card in deck.Resources)
            {
                sb.AppendLine(FormatPlayMeccgCardName(card.Name));
            }
            foreach (var card in deck.Hazards)
            {
                sb.AppendLine(FormatPlayMeccgCardName(card.Name));
            }
            sb.AppendLine();

            // Sideboard
            sb.AppendLine("####");
            sb.AppendLine("Sideboard");
            sb.AppendLine("####").AppendLine();
            foreach (var card in deck.Sideboard)
            {
                sb.AppendLine(FormatPlayMeccgCardName(card.Name));
            }
            sb.AppendLine();

            // Sites
            sb.AppendLine("####");
            sb.AppendLine("Sites");
            sb.AppendLine("####").AppendLine();
            foreach (var card in deck.Sites)
            {
                sb.AppendLine(FormatPlayMeccgCardName(card.Name));
            }
            sb.AppendLine();

            File.WriteAllText(filePath, sb.ToString(), ansiEncoding);
        }

        public static void ExportToCardnum(Deck deck, string filePath)
        {
            var sb = new StringBuilder();

            foreach (DeckSectionType sectionType in Enum.GetValues<DeckSectionType>())
            {
                sb.AppendLine(sectionType.ToString());
                sb.AppendLine();
                foreach (var card in deck.GetSection(sectionType))
                {
                    if (!string.IsNullOrEmpty(card.FullCode))
                    {
                        sb.AppendLine($"1 {card.FullCode}");
                    }
                }
                sb.AppendLine();
            }

            File.WriteAllText(filePath, sb.ToString(), Encoding.UTF8);
        }

        public static void ExportToArchive(Deck deck, string filePath)
        {
            string[] archiveCategories =
            [
                "Minor Item", "Major Item", "Greater Item", "Gold Ring Item", "Special Item",
                "Resource Short", "Resource Long", "Resource Permanent", "Ally", "Faction",
                "Creature Unique", "Creature", "Hazard Short", "Hazard Long", "Hazard Permanent",
                "Dunadan", "Dwarf", "Elf", "Hobbit", "Man (Wose)", "Wizard",
                "Free-hold", "Border-hold", "Ruins & Lairs", "Shadow-hold", "Dark-hold", "Region"
            ];

            int totalArchived = 0;
            var cardDataByCategory = new Dictionary<string, Dictionary<string, List<string>>>(StringComparer.OrdinalIgnoreCase);

            foreach (string cat in archiveCategories)
            {
                cardDataByCategory[cat] = new Dictionary<string, List<string>>(StringComparer.OrdinalIgnoreCase);
            }

            foreach (DeckSectionType sectionType in Enum.GetValues<DeckSectionType>())
            {
                foreach (var card in deck.GetSection(sectionType))
                {
                    string primary = card.Primary;
                    string secondary = TruncateSlash(card.Secondary);
                    string unique = card.Unique;
                    string race = card.Race;
                    string site = card.Site;

                    string categoryKey = GetArchiveCategoryKey(primary, secondary, unique, race, site);
                    if (string.IsNullOrEmpty(categoryKey) || !cardDataByCategory.TryGetValue(categoryKey, out var setsInCategory))
                    {
                        continue;
                    }

                    string setKey = card.Set;
                    if (!setsInCategory.TryGetValue(setKey, out var cardsInSet))
                    {
                        cardsInSet = [];
                        setsInCategory[setKey] = cardsInSet;
                    }

                    cardsInSet.Add(card.Name);
                    totalArchived++;
                }
            }

            using var writer = new StreamWriter(filePath, false, Encoding.UTF8);
            writer.WriteLine($"--- {filePath} ({totalArchived} cards) ---");
            writer.WriteLine();

            foreach (var categoryEntry in cardDataByCategory)
            {
                string categoryTitle = categoryEntry.Key;
                var setsInThisCategory = categoryEntry.Value;

                writer.WriteLine($"--- CATEGORY: {categoryTitle} ---");

                foreach (var setEntry in setsInThisCategory)
                {
                    string setTitle = setEntry.Key;
                    var cardsInThisSet = setEntry.Value;

                    if (cardsInThisSet.Count == 0)
                    {
                        continue;
                    }

                    writer.WriteLine($"\tSET: {setTitle} ({cardsInThisSet.Count})");
                    foreach (string cardName in cardsInThisSet)
                    {
                        writer.WriteLine($"\t\t{cardName}");
                    }
                }
                writer.WriteLine();
            }
        }

        public static void ExportToTts(IReadOnlyList<Card> cards, string filePath)
        {
            var sb = new StringBuilder();
            sb.Append("{\n\t\"ObjectStates\": [\n\t\t{\n\t\t\t\"Name\": \"Deck\",\n");
            sb.Append(GetTtsTransform(3));
            sb.Append("\t\t\t\"DeckIDs\": [\n");

            for (int i = 0; i < cards.Count; i++)
            {
                sb.Append($"\t\t\t\t{(i + 1) * 100}");
                if (i != cards.Count - 1) sb.Append(',');
                sb.Append('\n');
            }
            sb.Append("\t\t\t],\n\t\t\t\"CustomDeck\": {\n");

            for (int i = 0; i < cards.Count; i++)
            {
                sb.Append(GetTtsCustomDeck(cards[i], i + 1, 4));
                if (i != cards.Count - 1) sb.Append(',');
                sb.Append('\n');
            }
            sb.Append("\t\t\t},\n\t\t\t\"ContainedObjects\": [\n");

            for (int i = 0; i < cards.Count; i++)
            {
                string escapedName = cards[i].Name.Replace("\"", "\\\"");
                sb.Append("\t\t\t\t{\n\t\t\t\t\t\"Name\": \"Card\",\n");
                sb.Append(GetTtsTransform(5));
                sb.Append("\t\t\t\t\t\"CustomDeck\": {\n");
                sb.Append(GetTtsCustomDeck(cards[i], i + 1, 6));
                sb.Append("\n\t\t\t\t\t},\n");
                sb.Append($"\t\t\t\t\t\"Nickname\": \"{escapedName}\",\n");
                sb.Append($"\t\t\t\t\t\"CardID\": \"{(i + 1) * 100}\"\n");
                sb.Append("\t\t\t\t}");
                if (i != cards.Count - 1) sb.Append(',');
                sb.Append('\n');
            }

            sb.Append("\t\t\t]\n\t\t}\n\t]\n}\n");
            File.WriteAllText(filePath, sb.ToString(), Encoding.UTF8);
        }

        #region HELPERS

        private static string FormatPlayMeccgCardName(string cardName)
        {
            if (cardName.Contains(" - "))
            {
                string cleanName = cardName.Replace("\"", "");
                int dashIndex = cleanName.IndexOf(" - ", StringComparison.Ordinal);
                string mainTitle = cleanName[..dashIndex].Trim();
                string subTitle = cleanName[(dashIndex + 3)..].Trim();
                return $"{mainTitle} ({subTitle})";
            }
            return cardName;
        }

        private static string TruncateSlash(string value)
        {
            if (string.IsNullOrEmpty(value)) return string.Empty;
            int slashIndex = value.IndexOf('/');
            return slashIndex >= 0 ? value[..slashIndex].Trim() : value.Trim();
        }

        private static string GetArchiveCategoryKey(string primary, string secondary, string unique, string race, string site)
        {
            if (primary.Equals("Resource", StringComparison.OrdinalIgnoreCase))
            {
                return secondary switch
                {
                    "Minor Item" => "Minor Item",
                    "Major Item" => "Major Item",
                    "Greater Item" => "Greater Item",
                    "Gold Ring Item" => "Gold Ring Item",
                    "Special Item" => "Special Item",
                    "Short-event" => "Resource Short",
                    "Long-event" => "Resource Long",
                    "Permanent-event" => "Resource Permanent",
                    "Ally" => "Ally",
                    "Faction" => "Faction",
                    _ => string.Empty
                };
            }

            if (secondary.Equals("Creature", StringComparison.OrdinalIgnoreCase))
            {
                return unique.Equals("unique", StringComparison.OrdinalIgnoreCase) ? "Creature Unique" : "Creature";
            }

            if (primary.Equals("Hazard", StringComparison.OrdinalIgnoreCase))
            {
                return secondary switch
                {
                    "Short-event" => "Hazard Short",
                    "Long-event" => "Hazard Long",
                    "Permanent-event" => "Hazard Permanent",
                    _ => string.Empty
                };
            }

            if (primary.Equals("Character", StringComparison.OrdinalIgnoreCase))
            {
                if (race.Equals("Dúnadan", StringComparison.OrdinalIgnoreCase)) return "Dunadan";
                return race switch
                {
                    "Dwarf" => "Dwarf",
                    "Elf" => "Elf",
                    "Hobbit" => "Hobbit",
                    "Man" => "Man (Wose)",
                    "Wizard" => "Wizard",
                    _ => string.Empty
                };
            }

            if (primary.Equals("Site", StringComparison.OrdinalIgnoreCase))
            {
                return site switch
                {
                    "Free-hold" => "Free-hold",
                    "Border-hold" => "Border-hold",
                    "Ruins & Lairs" => "Ruins & Lairs",
                    "Shadow-hold" => "Shadow-hold",
                    "Dark-hold" => "Dark-hold",
                    "Region" => "Region",
                    _ => string.Empty
                };
            }

            if (primary.Equals("Region", StringComparison.OrdinalIgnoreCase))
            {
                return "Region";
            }

            return string.Empty;
        }

        private static string GetTtsTransform(int tabCount)
        {
            string tabs = new('\t', tabCount);
            return $"{tabs}\"Transform\": {{\n{tabs}\t\"RotY\": 180.0,\n{tabs}\t\"RotZ\": 180.0,\n{tabs}\t\"ScaleX\": 1.0,\n{tabs}\t\"ScaleY\": 1.0,\n{tabs}\t\"ScaleZ\": 1.0\n{tabs}}},\n";
        }

        private static string GetTtsCustomDeck(Card card, int index, int tabCount)
        {
            string tabs = new('\t', tabCount);
            return $"{tabs}\"{index}\": {{\n" +
                   $"{tabs}\t\"FaceURL\": \"https://cardnum.net/img/cards/{card.Set}/{card.ImageName}\",\n" +
                   $"{tabs}\t\"BackURL\": \"https://i.imgur.com/gUPyTI4.jpg\",\n" +
                   $"{tabs}\t\"BackIsHidden\": \"true\",\n" +
                   $"{tabs}\t\"NumWidth\": 1,\n" +
                   $"{tabs}\t\"NumHeight\": 1\n" +
                   $"{tabs}}}";
        }

        #endregion
    }
}

using System;
using System.Collections.Generic;

namespace MECCG_Deck_Builder
{
    public sealed class DeckGenerationRuleSet
    {
        public string DeckTitle { get; set; } = "Generated Deck";
        public string RuleSetType { get; set; } = "SequentialRules";
        public string Version { get; set; } = "1.0";
        public List<DeckGenerationRule> Rules { get; set; } = [];
    }

    public sealed class DeckGenerationChoice
    {
        public string Name { get; set; } = string.Empty;
        public string DeckTitle { get; set; } = string.Empty;
        public int Weight { get; set; } = 1;
        public List<DeckGenerationRule> Rules { get; set; } = [];
    }

    public sealed class DeckGenerationRule
    {
        public string RuleType { get; set; } = "FilterQuery";
        public string Name { get; set; } = string.Empty;
        public string SaveAs { get; set; } = string.Empty;
        public string Section { get; set; } = "Resources";
        public int Count { get; set; } = 1;
        public List<string> Sets { get; set; } = [];
        public Dictionary<string, string> Attributes { get; set; } = new(StringComparer.OrdinalIgnoreCase);
        public Dictionary<string, string> Categories { get; set; } = new(StringComparer.OrdinalIgnoreCase);
        public DeckGenerationRule Fallback { get; set; }
        public List<DeckGenerationChoice> Choices { get; set; } = [];
    }

    public sealed class DeckRuleExecutionLog
    {
        public string RuleName { get; init; } = string.Empty;
        public string Section { get; init; } = string.Empty;
        public int RequestedCount { get; init; }
        public int AddedCount { get; init; }
        public bool IsShortfall => AddedCount < RequestedCount;
    }

    public sealed class DeckGenerationResult
    {
        public Deck Deck { get; init; } = new();
        public List<DeckRuleExecutionLog> Logs { get; init; } = [];
        public bool Success { get; init; }
        public string ErrorMessage { get; init; } = string.Empty;
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.RegularExpressions;
using Newtonsoft.Json;

namespace MECCG_Deck_Builder
{
    public static class DeckGenerationService
    {
#pragma warning disable SYSLIB1045 // Use 'GeneratedRegexAttribute'
        private static readonly Regex PlaceholderRegex = new(
            @"\{([a-zA-Z0-9_]+)\.(?:(?:Category|Tag):([^}]+)|([a-zA-Z0-9_]+))\}",
            RegexOptions.Compiled | RegexOptions.IgnoreCase);
#pragma warning restore SYSLIB1045

        public static DeckGenerationRuleSet LoadRuleSetFromJson(string json)
        {
            if (string.IsNullOrWhiteSpace(json)) return null;
            return JsonConvert.DeserializeObject<DeckGenerationRuleSet>(json);
        }

        public static string SaveRuleSetToJson(DeckGenerationRuleSet ruleSet)
        {
            return JsonConvert.SerializeObject(ruleSet, Formatting.Indented);
        }

        public static DeckGenerationResult GenerateDeck(
            IEnumerable<Card> catalogCards,
            ISet<string> defaultSets,
            CardFilterService filterService,
            DeckGenerationRuleSet ruleSet)
        {
            if (ruleSet == null || ruleSet.Rules == null || ruleSet.Rules.Count == 0)
            {
                return new DeckGenerationResult
                {
                    Success = false,
                    ErrorMessage = "The rule set contains no rules."
                };
            }

            var deck = new Deck
            {
                Title = !string.IsNullOrWhiteSpace(ruleSet.DeckTitle) ? ruleSet.DeckTitle : "Generated Deck"
            };

            var cardCountsByName = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
            var contextVariables = new Dictionary<string, List<Card>>(StringComparer.OrdinalIgnoreCase);
            var logs = new List<DeckRuleExecutionLog>();
            var allCards = catalogCards?.ToList() ?? [];

            foreach (var rule in ruleSet.Rules)
            {
                ExecuteRule(rule, deck, cardCountsByName, logs, allCards, defaultSets, filterService, contextVariables);
            }

            deck.SortSections();

            return new DeckGenerationResult
            {
                Deck = deck,
                Logs = logs,
                Success = true
            };
        }

        private static void ExecuteRule(
            DeckGenerationRule rule,
            Deck deck,
            Dictionary<string, int> cardCountsByName,
            List<DeckRuleExecutionLog> logs,
            IReadOnlyList<Card> allCards,
            ISet<string> defaultSets,
            CardFilterService filterService,
            Dictionary<string, List<Card>> contextVariables = null)
        {
            if (rule == null) return;

            contextVariables ??= new Dictionary<string, List<Card>>(StringComparer.OrdinalIgnoreCase);

            // Handle RandomChoice / ChoiceGroup ("OR" branches)
            if (IsChoiceRule(rule))
            {
                var validChoices = rule.Choices?.Where(c => c != null && c.Rules != null && c.Rules.Count > 0).ToList() ?? [];
                if (validChoices.Count == 0) return;

                int totalWeight = validChoices.Sum(c => Math.Max(1, c.Weight));
                int roll = Random.Shared.Next(totalWeight);
                int cumulative = 0;
                DeckGenerationChoice chosen = validChoices[0];

                foreach (var c in validChoices)
                {
                    cumulative += Math.Max(1, c.Weight);
                    if (roll < cumulative)
                    {
                        chosen = c;
                        break;
                    }
                }

                if (!string.IsNullOrWhiteSpace(chosen.DeckTitle))
                {
                    deck.Title = chosen.DeckTitle;
                }

                logs.Add(new DeckRuleExecutionLog
                {
                    RuleName = $"[Branch Selected] {rule.Name} -> '{chosen.Name}'",
                    Section = "-",
                    RequestedCount = 0,
                    AddedCount = 0
                });

                foreach (var subRule in chosen.Rules)
                {
                    ExecuteRule(subRule, deck, cardCountsByName, logs, allCards, defaultSets, filterService, contextVariables);
                }
                return;
            }

            // Standard FilterQuery Rule
            if (rule.Count <= 0) return;

            if (!Enum.TryParse<DeckSectionType>(rule.Section, true, out var sectionType))
            {
                sectionType = DeckSectionType.Resources;
            }

            ISet<string> ruleSets = (rule.Sets != null && rule.Sets.Count > 0)
                ? new HashSet<string>(rule.Sets, StringComparer.OrdinalIgnoreCase)
                : defaultSets;

            // 1. Resolve runtime variable placeholders in Attributes & Categories
            var resolvedAttributes = new Dictionary<string, (string RawTemplate, string ResolvedValue)>(StringComparer.OrdinalIgnoreCase);
            if (rule.Attributes != null)
            {
                foreach (var (attrKey, rawVal) in rule.Attributes)
                {
                    if (string.IsNullOrWhiteSpace(attrKey)) continue;
                    string resolved = ResolvePlaceholders(rawVal, contextVariables, filterService);
                    resolvedAttributes[attrKey] = (rawVal, resolved);
                }
            }

            var resolvedCategories = new Dictionary<string, (string RawTemplate, string ResolvedValue)>(StringComparer.OrdinalIgnoreCase);
            if (rule.Categories != null)
            {
                foreach (var (catKey, rawVal) in rule.Categories)
                {
                    if (string.IsNullOrWhiteSpace(catKey)) continue;
                    string resolved = ResolvePlaceholders(rawVal, contextVariables, filterService);
                    resolvedCategories[catKey] = (rawVal, resolved);
                }
            }

            // 2. Filter candidates
            var candidates = allCards.Where(c =>
            {
                if (ruleSets != null && ruleSets.Count > 0 && !ruleSets.Contains(c.Set))
                {
                    return false;
                }

                // Attribute evaluation
                foreach (var (attrKey, (rawTemplate, resolvedVal)) in resolvedAttributes)
                {
                    if (!string.IsNullOrWhiteSpace(rawTemplate) && string.IsNullOrWhiteSpace(resolvedVal))
                    {
                        return false;
                    }

                    if (!string.IsNullOrWhiteSpace(resolvedVal))
                    {
                        var allowedValues = resolvedVal.Split(';', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
                        if (!allowedValues.Any(v =>
                            v == "*" ||
                            string.Equals(v, "All", StringComparison.OrdinalIgnoreCase) ||
                            CardFilterService.MatchesCardnumCriterion(c, attrKey, v)))
                        {
                            return false;
                        }
                    }
                }

                // Enhanced Category & Tag evaluation:
                if (filterService != null)
                {
                    foreach (var (catKey, (rawTemplate, resolvedVal)) in resolvedCategories)
                    {
                        if (!string.IsNullOrWhiteSpace(rawTemplate) && string.IsNullOrWhiteSpace(resolvedVal))
                        {
                            return false;
                        }

                        if (!string.IsNullOrWhiteSpace(resolvedVal))
                        {
                            var allowedTags = resolvedVal.Split(';', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
                            if (!allowedTags.Any(t =>
                                t == "*" ||
                                string.Equals(t, "All", StringComparison.OrdinalIgnoreCase) ||
                                filterService.MatchesCustomCriterion(c.Id, catKey, t)))
                            {
                                return false;
                            }
                        }
                    }
                }

                return true;
            }).ToList();

            // 3. Sample candidates with tiered variety-first distribution
            int addedForThisRule = 0;
            var targetSection = deck.GetSection(sectionType);
            var newlyAdded = new List<Card>();

            while (addedForThisRule < rule.Count)
            {
                var available = candidates.Where(c => CanAddCard(c, cardCountsByName)).ToList();
                if (available.Count == 0) break;

                int minCount = available.Min(c => cardCountsByName.GetValueOrDefault(c.Name, 0));

                var tierGroups = available
                    .Where(c => cardCountsByName.GetValueOrDefault(c.Name, 0) == minCount)
                    .GroupBy(c => c.Name, StringComparer.OrdinalIgnoreCase)
                    .ToList();

                if (tierGroups.Count == 0) break;

                int groupIndex = Random.Shared.Next(tierGroups.Count);
                var matchingReprints = tierGroups[groupIndex].ToList();
                var selectedCard = matchingReprints[Random.Shared.Next(matchingReprints.Count)];

                targetSection.Add(selectedCard);
                deck.IncludedSets.Add(selectedCard.Set);
                newlyAdded.Add(selectedCard);

                int currentCount = cardCountsByName.GetValueOrDefault(selectedCard.Name, 0) + 1;
                cardCountsByName[selectedCard.Name] = currentCount;
                addedForThisRule++;
            }

            // 4. Capture selected cards to variable context if SaveAs is specified
            if (!string.IsNullOrWhiteSpace(rule.SaveAs) && newlyAdded.Count > 0)
            {
                contextVariables[rule.SaveAs] = newlyAdded;
            }

            // 5. If shortfall occurred and a Fallback rule is defined, execute it for remaining count
            if (addedForThisRule < rule.Count && rule.Fallback != null)
            {
                int remainingNeeded = rule.Count - addedForThisRule;
                rule.Fallback.Count = remainingNeeded;

                if (string.IsNullOrWhiteSpace(rule.Fallback.Section))
                {
                    rule.Fallback.Section = sectionType.ToString();
                }

                int countBefore = targetSection.Count;
                ExecuteRule(rule.Fallback, deck, cardCountsByName, logs, allCards, defaultSets, filterService, contextVariables);
                int addedByFallback = targetSection.Count - countBefore;

                return;
            }
        }

        private static string ResolvePlaceholders(
            string template,
            Dictionary<string, List<Card>> contextVariables,
            CardFilterService filterService)
        {
            if (string.IsNullOrWhiteSpace(template) || !template.Contains('{'))
            {
                return template ?? string.Empty;
            }

            return PlaceholderRegex.Replace(template, match =>
            {
                string varName = match.Groups[1].Value;
                if (!contextVariables.TryGetValue(varName, out var cards) || cards.Count == 0)
                {
                    return string.Empty;
                }

                var resolvedValues = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

                if (match.Groups[2].Success && !string.IsNullOrWhiteSpace(match.Groups[2].Value))
                {
                    // Custom taxonomy tag lookup: {Variable.Category:Category Name} or {Variable.Tag:Category Name}
                    string category = match.Groups[2].Value.Trim();
                    if (filterService != null)
                    {
                        foreach (var card in cards)
                        {
                            var tags = filterService.GetCardTagsForCategory(card.Id, category);
                            foreach (var tag in tags)
                            {
                                if (!string.IsNullOrWhiteSpace(tag))
                                {
                                    resolvedValues.Add(tag.Trim());
                                }
                            }
                        }
                    }
                }
                else if (match.Groups[3].Success && !string.IsNullOrWhiteSpace(match.Groups[3].Value))
                {
                    // Official rules attribute lookup: {Variable.AttributeName}
                    string attrName = match.Groups[3].Value.Trim();
                    foreach (var card in cards)
                    {
                        string val = card.GetAttribute(attrName);
                        if (!string.IsNullOrWhiteSpace(val))
                        {
                            var parts = val.Split([';', ','], StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
                            foreach (var part in parts)
                            {
                                resolvedValues.Add(part);
                            }
                        }
                    }
                }

                return resolvedValues.Count > 0 ? string.Join("; ", resolvedValues) : string.Empty;
            }).Trim();
        }

        private static bool IsChoiceRule(DeckGenerationRule rule)
        {
            if (rule == null) return false;
            return string.Equals(rule.RuleType, "RandomChoice", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(rule.RuleType, "Choice", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(rule.RuleType, "OneOf", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(rule.RuleType, "Or", StringComparison.OrdinalIgnoreCase) ||
                   (rule.Choices != null && rule.Choices.Count > 0);
        }

        private static bool CanAddCard(Card card, Dictionary<string, int> cardCountsByName)
        {
            int currentCount = cardCountsByName.GetValueOrDefault(card.Name, 0);
            int maxAllowed = IsUniqueCard(card) ? 1 : 3;
            return currentCount < maxAllowed;
        }

        private static bool IsUniqueCard(Card card)
        {
            return string.Equals(card.Unique, "Unique", StringComparison.OrdinalIgnoreCase);
        }
    }
}

namespace MECCG_Deck_Builder
{
    public enum DeckSectionType
    {
        Pool,
        Resources,
        Hazards,
        Sideboard,
        Sites
    }
}

namespace MECCG_Deck_Builder
{
    public enum FilterType
    {
        Cardnum,
        Custom
    }

    public sealed record FilterCriterion(FilterType Type, string Key, string Value)
    {
        public bool IsActive => !string.IsNullOrWhiteSpace(Key) && !string.IsNullOrWhiteSpace(Value);
    }
}

using NaturalSort.Extension;
using Newtonsoft.Json;
using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using System.Windows.Forms;

namespace MECCG_Deck_Builder
{
    internal partial class Form1 : Form
    {
        private sealed class FilterSlot(int index, FilterType type, ComboBox keyBox, ComboBox valueBox)
        {
            public int Index { get; } = index;
            public FilterType Type { get; } = type;
            public ComboBox KeyBox { get; } = keyBox;
            public ComboBox ValueBox { get; } = valueBox;

            public string CurrentKey => KeyBox.Text.Trim();
            public string CurrentValue => ValueBox.Text.Trim();

            public FilterCriterion ToCriterion() => new(Type, CurrentKey, CurrentValue);
        }

        private readonly CardCatalogService _catalogService = new();
        private readonly CardFilterService _filterService = new();
        private readonly Deck _currentDeck = new();
        private readonly CardImageCache _cardImageCache = new();

        private readonly FilterSlot[] _filterSlots;
        private bool _isUpdatingFilters;

        private List<Card> _masterCards = [];
        private Card _inspectedCard;
        private ListBox _callingListBox;
        private int _selectedMasterIndex;
        private int _selectedTabIndex;
        private CancellationTokenSource _imageLoadCts;
        private Rectangle _dragBoxFromMouseDown = Rectangle.Empty;
        private string _lastDeckRulesFilePath;

        internal Form1()
        {
            InitializeComponent();

            _filterSlots = [
                new FilterSlot(0, FilterType.Cardnum, ComboBoxKey1, ComboBoxValue1),
                new FilterSlot(1, FilterType.Cardnum, ComboBoxKey2, ComboBoxValue2),
                new FilterSlot(2, FilterType.Custom, ComboBoxKey3, ComboBoxValue3),
                new FilterSlot(3, FilterType.Custom, ComboBoxKey4, ComboBoxValue4)
            ];

            InitializeFilterClearing();
            InitializeTaxonomyInspector();

            _catalogService.WarningOccurred += (s, msg) =>
                MessageBox.Show(msg, Constants.AppTitle, MessageBoxButtons.OK, MessageBoxIcon.Warning);

            Shown += Form1_Shown;
        }

        private async void Form1_Shown(object sender, EventArgs e)
        {
            Enabled = false;
            Text = $"{Constants.AppTitle} - Initializing Card Catalog...";

            try
            {
                await _catalogService.InitializeAsync();
                LoadBaselineRulesTags(); // Auto-load Rules_Support_Tags.json if present
                CreateMenus();
                RefreshFilterKeyDropdowns();
                PopulateAssignCategories();
                UpdateFacetedFilters();
                UpdateFormTitle();
                SetRightPaneMode(false); // Default to Deck Builder tab view
            }
            finally
            {
                Enabled = true;
                UpdateFormTitle();
            }
        }

        private void LoadBaselineRulesTags()
        {
            try
            {
                string path = StoragePathService.ResolveDataFilePath("Rules_Support_Tags.json");
                if (File.Exists(path))
                {
                    string json = File.ReadAllText(path);
                    var dto = JsonConvert.DeserializeObject<OpenCloseFilter>(json);
                    if (dto != null)
                    {
                        _filterService.LoadCustomFilters(dto.Filters, dto.Cards, _catalogService);
                    }
                }
            }
            catch
            {
                // Baseline load fails gracefully without blocking catalog startup
            }
        }

        private void CreateMenus()
        {
            // Keep Catalog dropdown open while ticking expansion sets
            ToolStripMenuCatalog.DropDown.Closing += (s, e) =>
            {
                if (e.CloseReason == ToolStripDropDownCloseReason.ItemClicked)
                {
                    e.Cancel = true;
                }
            };

            var resources = new System.ComponentModel.ComponentResourceManager(typeof(Form1));
            ToolStripMenuFilterOpen.Image = (Image)resources.GetObject("OpenToolStripMenuItem.Image");
            ToolStripMenuFilterSave.Image = (Image)resources.GetObject("ExportToolStripMenuItem.Image");

            PopulateSetMenuItems();
        }

        private void PopulateSetMenuItems()
        {
            _isUpdatingFilters = true;
            try
            {
                var existingSetItems = ToolStripMenuCatalog.DropDownItems
                    .OfType<ToolStripMenuItem>()
                    .Where(item => item.Tag is string)
                    .ToList();

                foreach (var item in existingSetItems)
                {
                    ToolStripMenuCatalog.DropDownItems.Remove(item);
                }

                var savedSets = new HashSet<string>(UserSettingsService.Current.SelectedSets ?? [], StringComparer.OrdinalIgnoreCase);
                int insertIndex = ToolStripMenuCatalog.DropDownItems.Count - 2;

                for (int i = 0; i < _catalogService.Sets.Count; i++)
                {
                    var set = _catalogService.Sets[i];
                    var menuItem = new ToolStripMenuItem(set.Name)
                    {
                        Tag = set.Code,
                        CheckOnClick = true
                    };
                    menuItem.CheckedChanged += ToolStripMenuSet_CheckedChanged;

                    bool shouldCheck = savedSets.Count > 0
                        ? savedSets.Contains(set.Code)
                        : (i == 0);

                    if (shouldCheck)
                    {
                        menuItem.Checked = true;
                        _currentDeck.IncludedSets.Add(set.Code);
                    }

                    ToolStripMenuCatalog.DropDownItems.Insert(insertIndex++, menuItem);
                }

                if (_currentDeck.IncludedSets.Count == 0 && _catalogService.Sets.Count > 0)
                {
                    var firstSet = _catalogService.Sets[0];
                    if (ToolStripMenuCatalog.DropDownItems.Count > 3 && ToolStripMenuCatalog.DropDownItems[3] is ToolStripMenuItem firstItem)
                    {
                        firstItem.Checked = true;
                    }
                    _currentDeck.IncludedSets.Add(firstSet.Code);
                }
            }
            finally
            {
                _isUpdatingFilters = false;
            }
        }

        private void PersistSelectedSets()
        {
            UserSettingsService.Current.SelectedSets = [.. _currentDeck.IncludedSets];
            UserSettingsService.SaveSettings();
        }

        private void RefreshFilterKeyDropdowns()
        {
            _isUpdatingFilters = true;
            try
            {
                SetKeyDropdownDataSource(ComboBoxKey1, _catalogService.GetFilterKeys());
                SetKeyDropdownDataSource(ComboBoxKey2, _catalogService.GetFilterKeys());
                SetKeyDropdownDataSource(ComboBoxKey3, _filterService.GetCustomKeyNames());
                SetKeyDropdownDataSource(ComboBoxKey4, _filterService.GetCustomKeyNames());
            }
            finally
            {
                _isUpdatingFilters = false;
            }
        }

        private static void SetKeyDropdownDataSource(ComboBox cb, IReadOnlyList<string> items)
        {
            string current = cb.Text.Trim();
            cb.DataSource = null;
            cb.DataSource = items;
            int idx = -1;
            for (int i = 0; i < items.Count; i++)
            {
                if (string.Equals(items[i], current, StringComparison.OrdinalIgnoreCase))
                {
                    idx = i;
                    break;
                }
            }
            if (idx >= 0)
            {
                cb.SelectedIndex = idx;
            }
            else if (items.Count > 0)
            {
                cb.SelectedIndex = 0;
            }
            else
            {
                cb.SelectedIndex = -1;
            }
        }

        #region RIGHT_PANE_MODE_AND_INSPECTOR

        private void InitializeTaxonomyInspector()
        {
            BtnModeDeck.Click += (s, e) => SetRightPaneMode(false);
            BtnModeTaxonomy.Click += (s, e) => SetRightPaneMode(true);

            CmbAssignCategory.SelectedIndexChanged += (s, e) => PopulateAssignTagsForCategory();
            CmbAssignCategory.TextChanged += (s, e) => PopulateAssignTagsForCategory();

            // Handle <Enter> key for rapid keyboard assignment
            CmbAssignCategory.KeyDown += CmbAssign_KeyDown;
            CmbAssignTag.KeyDown += CmbAssign_KeyDown;

            BtnAssignTag.Click += BtnAssignTag_Click;
            BtnRemoveTag.Click += BtnRemoveTag_Click;
            BtnAuthorTag.Click += BtnAuthorTag_Click;
        }

        private void CmbAssign_KeyDown(object sender, KeyEventArgs e)
        {
            if (e.KeyCode == Keys.Enter)
            {
                e.Handled = true;
                e.SuppressKeyPress = true; // Silences the Windows ding sound

                if (sender == CmbAssignCategory && string.IsNullOrWhiteSpace(CmbAssignTag.Text))
                {
                    // If hitting Enter on an empty Category box, jump straight to Tag
                    CmbAssignTag.Focus();
                }
                else
                {
                    // Trigger the "+ Assign" button directly
                    BtnAssignTag.PerformClick();
                }
            }
        }

        private void SetRightPaneMode(bool isTaxonomy)
        {
            if (isTaxonomy)
            {
                BtnModeTaxonomy.BackColor = SystemColors.Window;
                BtnModeTaxonomy.Font = new Font(Font, FontStyle.Bold);
                BtnModeDeck.BackColor = SystemColors.Control;
                BtnModeDeck.Font = new Font(Font, FontStyle.Regular);

                TabControlDeck.Visible = false;
                PanelTaxonomy.Visible = true;

                PopulateAssignCategories();
                SyncAssignCategoryWithFilterSlots();
                UpdateTaxonomyView(_inspectedCard);
            }
            else
            {
                BtnModeDeck.BackColor = SystemColors.Window;
                BtnModeDeck.Font = new Font(Font, FontStyle.Bold);
                BtnModeTaxonomy.BackColor = SystemColors.Control;
                BtnModeTaxonomy.Font = new Font(Font, FontStyle.Regular);

                PanelTaxonomy.Visible = false;
                TabControlDeck.Visible = true;
            }
        }

        private void SyncAssignCategoryWithFilterSlots()
        {
            string slot3Cat = ComboBoxKey3.Text.Trim();
            string slot3Val = ComboBoxValue3.Text.Trim();
            string slot4Cat = ComboBoxKey4.Text.Trim();
            string slot4Val = ComboBoxValue4.Text.Trim();

            if (!string.IsNullOrWhiteSpace(slot3Cat))
            {
                CmbAssignCategory.Text = slot3Cat;
                PopulateAssignTagsForCategory(!string.IsNullOrWhiteSpace(slot3Val) ? slot3Val : null);
            }
            else if (!string.IsNullOrWhiteSpace(slot4Cat))
            {
                CmbAssignCategory.Text = slot4Cat;
                PopulateAssignTagsForCategory(!string.IsNullOrWhiteSpace(slot4Val) ? slot4Val : null);
            }
        }

        private void PopulateAssignCategories()
        {
            string prevCategory = CmbAssignCategory.Text.Trim();
            CmbAssignCategory.Items.Clear();

            var keys = _filterService.GetCustomKeyNames().Where(k => !string.IsNullOrWhiteSpace(k)).ToList();
            foreach (var k in keys)
            {
                CmbAssignCategory.Items.Add(k);
            }

            // 1. Only preserve previous category if it still exists in the taxonomy!
            var survivingCategory = keys.FirstOrDefault(k => string.Equals(k, prevCategory, StringComparison.OrdinalIgnoreCase));

            if (!string.IsNullOrEmpty(survivingCategory))
            {
                CmbAssignCategory.Text = survivingCategory;
            }
            else if (keys.Count > 0)
            {
                // Fall back to Slot 3 (if valid), then Slot 4 (if valid), or index 0
                string slot3 = ComboBoxKey3.Text.Trim();
                string slot4 = ComboBoxKey4.Text.Trim();

                var matchSlot3 = keys.FirstOrDefault(k => string.Equals(k, slot3, StringComparison.OrdinalIgnoreCase));
                var matchSlot4 = keys.FirstOrDefault(k => string.Equals(k, slot4, StringComparison.OrdinalIgnoreCase));

                if (!string.IsNullOrEmpty(matchSlot3))
                {
                    CmbAssignCategory.Text = matchSlot3;
                }
                else if (!string.IsNullOrEmpty(matchSlot4))
                {
                    CmbAssignCategory.Text = matchSlot4;
                }
                else
                {
                    CmbAssignCategory.SelectedIndex = 0;
                }
            }
            else
            {
                CmbAssignCategory.SelectedIndex = -1;
                CmbAssignCategory.Text = string.Empty;
            }

            PopulateAssignTagsForCategory();
        }

        private void PopulateAssignTagsForCategory(string tagToSelect = null)
        {
            string category = CmbAssignCategory.Text.Trim();
            string targetTag = !string.IsNullOrWhiteSpace(tagToSelect)
                ? tagToSelect.Trim().TrimStart('✓', ' ')
                : CmbAssignTag.Text.Trim().TrimStart('✓', ' ');

            CmbAssignTag.Items.Clear();

            if (string.IsNullOrWhiteSpace(category))
            {
                CmbAssignTag.SelectedIndex = -1;
                CmbAssignTag.Text = string.Empty;
                return;
            }

            var tags = _filterService.GetCustomKeyValues(category).Where(v => !string.IsNullOrWhiteSpace(v)).ToList();
            var cardTags = (_inspectedCard != null)
                ? _filterService.GetCardTagsForCategory(_inspectedCard.Id, category)
                : [];

            foreach (var t in tags)
            {
                bool isAssigned = cardTags.Contains(t, StringComparer.OrdinalIgnoreCase);
                string displayTag = isAssigned ? $"✓ {t}" : t;
                CmbAssignTag.Items.Add(displayTag);
            }

            // 1. Prioritize target tag ONLY if it exists in the surviving tags list
            if (!string.IsNullOrEmpty(targetTag))
            {
                int matchIdx = -1;
                for (int i = 0; i < CmbAssignTag.Items.Count; i++)
                {
                    string raw = CmbAssignTag.Items[i].ToString().TrimStart('✓', ' ');
                    if (string.Equals(raw, targetTag, StringComparison.OrdinalIgnoreCase))
                    {
                        matchIdx = i;
                        break;
                    }
                }
                if (matchIdx >= 0)
                {
                    CmbAssignTag.SelectedIndex = matchIdx;
                    return;
                }
            }

            // 2. Otherwise default to the card's first assigned tag if any
            if (cardTags.Count > 0)
            {
                int matchIdx = -1;
                for (int i = 0; i < CmbAssignTag.Items.Count; i++)
                {
                    string raw = CmbAssignTag.Items[i].ToString().TrimStart('✓', ' ');
                    if (string.Equals(raw, cardTags[0], StringComparison.OrdinalIgnoreCase))
                    {
                        matchIdx = i;
                        break;
                    }
                }
                if (matchIdx >= 0)
                {
                    CmbAssignTag.SelectedIndex = matchIdx;
                    return;
                }
            }

            // 3. Fall back to index 0 if tags exist, otherwise cleanly clear the box
            if (CmbAssignTag.Items.Count > 0)
            {
                CmbAssignTag.SelectedIndex = 0;
            }
            else
            {
                CmbAssignTag.SelectedIndex = -1;
                CmbAssignTag.Text = string.Empty;
            }
        }

        private void UpdateTaxonomyView(Card card)
        {
            if (card == null)
            {
                LblTaxonomyCardTitle.Text = "(No card selected)";
                RichTextBoxTaxonomy.Clear();
                return;
            }

            LblTaxonomyCardTitle.Text = $"{card.Name} ({card.Set})";

            RichTextBoxTaxonomy.SuspendLayout();
            RichTextBoxTaxonomy.Clear();

            Color headerColor = Color.FromArgb(26, 54, 93);    // Slate Navy #1A365D
            Color keyColor = Color.FromArgb(74, 85, 104);       // Muted Gray #4A5568
            Color valColor = Color.FromArgb(26, 32, 44);        // Crisp Dark #1A202C
            Color emptyColor = Color.FromArgb(160, 174, 192);   // Italic Muted Gray #A0AEC0
            Color tagColor = Color.FromArgb(19, 78, 74);        // Deep Teal #134E4A

            using var headerFont = new Font("Segoe UI", 9.0f, FontStyle.Bold);
            using var monoRegularFont = new Font("Consolas", 8.25f, FontStyle.Regular);
            using var monoBoldFont = new Font("Consolas", 8.25f, FontStyle.Bold);
            using var italicFont = new Font("Consolas", 8.25f, FontStyle.Italic);

            void AppendHeader(string text)
            {
                RichTextBoxTaxonomy.SelectionStart = RichTextBoxTaxonomy.TextLength;
                RichTextBoxTaxonomy.SelectionLength = 0;
                RichTextBoxTaxonomy.SelectionColor = headerColor;
                RichTextBoxTaxonomy.SelectionFont = headerFont;
                RichTextBoxTaxonomy.AppendText(text);
            }

            // --- 1. OFFICIAL ATTRIBUTES ---
            AppendHeader("=== OFFICIAL ATTRIBUTES ===" + Environment.NewLine);

            // Suppress legacy placeholder Secondary when it merely duplicates Primary (e.g., site/Site, region/Region)
            string displaySecondary = string.Equals(card.Primary, card.Secondary, StringComparison.OrdinalIgnoreCase)
                ? string.Empty
                : card.Secondary;

            // Suppress composite unparsed Playable string for official published sets to save vertical space;
            // preserve it for Dreamcards that may use custom text strings.
            string displayPlayable = card.Dreamcard
                ? card.Playable
                : string.Empty;

            var attrPairs = new List<(string Key, string Value)>
    {
        ("Primary", card.Primary),
        ("Secondary", displaySecondary),
        ("Alignment", card.Alignment),
        ("Race", card.Race),
        ("Subrace", card.Subrace),
        ("Skill", card.Skill),
        ("Mind", card.Mind),
        ("Direct", card.Direct),
        ("Prowess", card.Prowess),
        ("Body", card.Body),
        ("Corruption", card.Corruption),
        ("Strikes", card.Strikes),
        ("Home", card.Home),
        ("Site", card.Site),
        ("Region", card.Region),
        ("Haven", card.Haven),
        ("MPs", card.MPs),
        ("Unique", card.Unique),
        ("Playable", displayPlayable),
        ("GoldRing", card.GoldRing),
        ("GreaterItem", card.GreaterItem),
        ("MajorItem", card.MajorItem),
        ("MinorItem", card.MinorItem),
        ("Information", card.Information),
        ("Palantiri", card.Palantiri),
        ("Scroll", card.Scroll),
        ("Hoard", card.Hoard),
        ("Specific", card.Specific),
        ("Artist", card.Artist)
    };

            var nonBlankAttrs = attrPairs.Where(p => !string.IsNullOrWhiteSpace(p.Value)).ToList();
            if (nonBlankAttrs.Count > 0)
            {
                int maxKeyLen = nonBlankAttrs.Max(p => p.Key.Length);
                foreach (var (k, v) in nonBlankAttrs)
                {
                    AppendWrappedMonospaceLine(k, v, maxKeyLen, keyColor, valColor, monoRegularFont, monoBoldFont);
                }
            }
            else
            {
                AppendSingleLine("  (None)" + Environment.NewLine, emptyColor, italicFont);
            }

            AppendSingleLine(Environment.NewLine, keyColor, monoRegularFont);

            // --- 2. CUSTOM TAXONOMY TAGS ---
            AppendHeader("=== ASSIGNED CUSTOM TAGS ===" + Environment.NewLine);

            var customPairs = _filterService.GetCardCustomFilterPairs(card.Id);
            if (customPairs.Count > 0)
            {
                int maxCatLen = Math.Min(16, customPairs.Max(p => p.Key.Length));
                foreach (var kvp in customPairs)
                {
                    AppendWrappedMonospaceLine(kvp.Key, kvp.Value, maxCatLen, keyColor, tagColor, monoRegularFont, monoBoldFont);
                }
            }
            else
            {
                AppendSingleLine("  (No custom tags assigned)" + Environment.NewLine, emptyColor, italicFont);
            }

            RichTextBoxTaxonomy.SelectionStart = 0;
            RichTextBoxTaxonomy.ScrollToCaret();
            RichTextBoxTaxonomy.ResumeLayout();
        }

        private void AppendSingleLine(string text, Color color, Font font)
        {
            RichTextBoxTaxonomy.SelectionStart = RichTextBoxTaxonomy.TextLength;
            RichTextBoxTaxonomy.SelectionLength = 0;
            RichTextBoxTaxonomy.SelectionColor = color;
            RichTextBoxTaxonomy.SelectionFont = font;
            RichTextBoxTaxonomy.AppendText(text);
        }

        private void AppendWrappedMonospaceLine(
            string key,
            string value,
            int maxKeyLen,
            Color keyColor,
            Color valColor,
            Font regularFont,
            Font boldFont)
        {
            if (string.IsNullOrWhiteSpace(value)) return;

            string paddedKey = key.PadRight(maxKeyLen);
            string prefix = $"  {paddedKey} : ";
            string indent = new(' ', prefix.Length);

            // 38 characters max per line prevents horizontal clipping on 306px pane width
            int availWidth = Math.Max(12, 38 - prefix.Length);
            var lines = WrapTokensToLines(value, availWidth);

            for (int i = 0; i < lines.Count; i++)
            {
                AppendSingleLine(i == 0 ? prefix : indent, keyColor, regularFont);
                AppendSingleLine(lines[i] + Environment.NewLine, valColor, boldFont);
            }
        }

        private static List<string> WrapTokensToLines(string text, int availWidth)
        {
            var lines = new List<string>();
            if (string.IsNullOrWhiteSpace(text)) return lines;

            // Semicolon-delimited lists (custom tags, resolved sites, skills)
            if (text.Contains(';'))
            {
                var tokens = text.Split(';', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
                var cur = new System.Text.StringBuilder();

                for (int i = 0; i < tokens.Length; i++)
                {
                    string token = tokens[i];
                    bool isLast = (i == tokens.Length - 1);
                    string tokenWithSep = isLast ? token : token + ";";

                    if (cur.Length == 0)
                    {
                        cur.Append(tokenWithSep);
                    }
                    else if (cur.Length + 1 + tokenWithSep.Length <= availWidth)
                    {
                        cur.Append(' ').Append(tokenWithSep);
                    }
                    else
                    {
                        lines.Add(cur.ToString());
                        cur.Clear();
                        cur.Append(tokenWithSep);
                    }
                }

                if (cur.Length > 0)
                {
                    lines.Add(cur.ToString());
                }

                return lines;
            }

            // Word-wrap long unbroken strings (e.g. Home site, Skill descriptions)
            var words = text.Split(' ', StringSplitOptions.RemoveEmptyEntries);
            var wordCur = new System.Text.StringBuilder();

            foreach (var w in words)
            {
                if (wordCur.Length == 0)
                {
                    wordCur.Append(w);
                }
                else if (wordCur.Length + 1 + w.Length <= availWidth)
                {
                    wordCur.Append(' ').Append(w);
                }
                else
                {
                    lines.Add(wordCur.ToString());
                    wordCur.Clear();
                    wordCur.Append(w);
                }
            }

            if (wordCur.Length > 0)
            {
                lines.Add(wordCur.ToString());
            }

            return lines;
        }

        private void BtnAssignTag_Click(object sender, EventArgs e)
        {
            if (_inspectedCard == null)
            {
                MessageBox.Show(this, "Please select a card first.", Constants.AppTitle, MessageBoxButtons.OK, MessageBoxIcon.Information);
                return;
            }

            string rawCategory = CmbAssignCategory.Text.Trim();
            string tagInput = CmbAssignTag.Text.Trim().TrimStart('✓', ' ');

            if (string.IsNullOrWhiteSpace(rawCategory))
            {
                MessageBox.Show(this, "Please enter or select a category.", "Assign Tag", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                CmbAssignCategory.Focus();
                return;
            }

            if (string.IsNullOrWhiteSpace(tagInput))
            {
                MessageBox.Show(this, "Please enter or select a tag.", "Assign Tag", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                CmbAssignTag.Focus();
                return;
            }

            // 1. Canonicalize Category
            var allCategories = _filterService.GetCustomKeyNames().Where(k => !string.IsNullOrWhiteSpace(k)).ToList();
            string category = allCategories.FirstOrDefault(c => string.Equals(c, rawCategory, StringComparison.OrdinalIgnoreCase)) ?? rawCategory;

            if (!allCategories.Contains(category, StringComparer.OrdinalIgnoreCase))
            {
                var res = MessageBox.Show(this,
                    $"Category '{category}' does not exist in your taxonomy.\n\nDo you want to create this new category?",
                    "New Category Confirmation",
                    MessageBoxButtons.YesNo,
                    MessageBoxIcon.Question);

                if (res != DialogResult.Yes) return;
            }

            // 2. Canonicalize each tag and guard against accidental typos
            var knownCategoryTags = _filterService.GetCustomKeyValues(category).Where(v => !string.IsNullOrWhiteSpace(v)).ToList();
            var rawTagParts = tagInput.Split(';', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
            var tagsToAssign = new List<string>();

            foreach (var rawTag in rawTagParts)
            {
                var canonicalMatch = knownCategoryTags.FirstOrDefault(t => string.Equals(t, rawTag, StringComparison.OrdinalIgnoreCase));
                if (canonicalMatch != null)
                {
                    // Existing tag: snaps to official catalog casing automatically
                    tagsToAssign.Add(canonicalMatch);
                }
                else
                {
                    // Unrecognized tag: prompt user to confirm it's intentional (not a typo)
                    var res = MessageBox.Show(this,
                        $"Tag '{rawTag}' is not currently registered under category '{category}'.\n\nDo you want to create and assign this new tag?",
                        "New Tag Confirmation",
                        MessageBoxButtons.YesNo,
                        MessageBoxIcon.Question);

                    if (res == DialogResult.Yes)
                    {
                        tagsToAssign.Add(rawTag);
                    }
                }
            }

            if (tagsToAssign.Count == 0) return;

            // 3. Assign tags
            foreach (var tag in tagsToAssign)
            {
                _filterService.AddCustomKeyName(category);
                _filterService.AddCustomKeyValue(category, tag);
                _filterService.AppendCardCustomTag(_inspectedCard.Id, category, tag);
            }

            RefreshFilterKeyDropdowns();
            UpdateFacetedFilters();
            UpdateTaxonomyView(_inspectedCard);
            PopulateAssignCategories();
            CmbAssignCategory.Text = category;

            // Select the first assigned tag with correct checkmark and catalog casing
            PopulateAssignTagsForCategory(tagsToAssign[0]);
        }

        private void BtnRemoveTag_Click(object sender, EventArgs e)
        {
            if (_inspectedCard == null) return;

            string category = CmbAssignCategory.Text.Trim();
            string tag = CmbAssignTag.Text.Trim().TrimStart('✓', ' ');

            var cardTags = _filterService.GetCardTagsForCategory(_inspectedCard.Id, category);

            if (!string.IsNullOrWhiteSpace(category) && !string.IsNullOrWhiteSpace(tag) && cardTags.Contains(tag, StringComparer.OrdinalIgnoreCase))
            {
                _filterService.RemoveCardCustomTag(_inspectedCard.Id, category, tag);
                UpdateFacetedFilters();
                UpdateTaxonomyView(_inspectedCard);

                // Re-populate and select the tag so it displays WITHOUT '✓ '
                PopulateAssignTagsForCategory(tag);
                return;
            }

            // Fallback context picker listing all tags currently on the card
            var allPairs = _filterService.GetCardCustomFilterPairs(_inspectedCard.Id);
            if (allPairs.Count == 0)
            {
                MessageBox.Show(this, $"No custom tags are currently assigned to '{_inspectedCard.Name}'.", "Remove Tag", MessageBoxButtons.OK, MessageBoxIcon.Information);
                return;
            }

            var removeMenu = new ContextMenuStrip();
            foreach (var (cat, val) in allPairs)
            {
                var catMenu = new ToolStripMenuItem(cat.Replace("&", "&&"));
                var tagList = val.Split(';', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
                foreach (var t in tagList)
                {
                    var item = new ToolStripMenuItem(t.Replace("&", "&&")) { Tag = (cat, t) };
                    item.Click += (s, ev) =>
                    {
                        if (((ToolStripMenuItem)s).Tag is (string c, string v))
                        {
                            _filterService.RemoveCardCustomTag(_inspectedCard.Id, c, v);
                            UpdateFacetedFilters();
                            UpdateTaxonomyView(_inspectedCard);
                            PopulateAssignTagsForCategory();
                        }
                    };
                    catMenu.DropDownItems.Add(item);
                }
                removeMenu.Items.Add(catMenu);
            }

            removeMenu.Show(BtnRemoveTag, new Point(0, BtnRemoveTag.Height));
        }

        private void BtnAuthorTag_Click(object sender, EventArgs e)
        {
            if (_inspectedCard == null)
            {
                MessageBox.Show(this, "Please select a card first.", Constants.AppTitle, MessageBoxButtons.OK, MessageBoxIcon.Information);
                return;
            }

            // Pass the currently active category into the dialog
            string initialCategory = CmbAssignCategory.Text.Trim();
            var result = AddTagDialog.Show(this, _inspectedCard.Name, _filterService, initialCategory);
            if (result.HasValue)
            {
                _filterService.AddCustomKeyName(result.Value.Key);
                _filterService.AddCustomKeyValue(result.Value.Key, result.Value.Value);
                _filterService.AppendCardCustomTag(_inspectedCard.Id, result.Value.Key, result.Value.Value);

                RefreshFilterKeyDropdowns();
                UpdateFacetedFilters();
                UpdateTaxonomyView(_inspectedCard);
                PopulateAssignCategories();
                CmbAssignCategory.Text = result.Value.Key;

                // Re-populate and select the new tag with '✓ '
                PopulateAssignTagsForCategory(result.Value.Value);
            }
        }

