            _lstPreview.Columns.Add("Category", 150);
            _lstPreview.Columns.Add("Extracted Tag", 250);

            _btnExportCsv = new Button
            {
                Text = "Export to CSV...",
                Location = new Point(350, 638),
                Size = new Size(130, 30)
            };
            _btnExportCsv.Click += BtnExportCsv_Click;

            _btnApply = new Button
            {
                Text = "Apply Tags to Catalog",
                Location = new Point(490, 638),
                Size = new Size(150, 30)
            };
            _btnApply.Click += BtnApply_Click;

            _btnClose = new Button
            {
                Text = "Close",
                Location = new Point(648, 638),
                Size = new Size(80, 30),
                DialogResult = DialogResult.Cancel
            };

            Controls.AddRange([grpSource, _btnTest, lblScopeHint, _lstPreview, _btnExportCsv, _btnApply, _btnClose]);
            CancelButton = _btnClose;

            FormClosing += (s, e) => SaveCurrentSettings();

            PopulateDropdowns();
        }

        private void PopulateDropdowns()
        {
            var settings = UserSettingsService.Current;

            _cmbHarvestAttribute.Items.Clear();
            _cmbRelSourceAttr.Items.Clear();
            _cmbRelTargetAttr.Items.Clear();
            _cmbRelLookupAttr.Items.Clear();

            var keys = _catalog.GetFilterKeys().Where(k => !string.IsNullOrWhiteSpace(k)).ToList();
            foreach (var k in keys)
            {
                _cmbHarvestAttribute.Items.Add(k);
                _cmbRelSourceAttr.Items.Add(k);
                _cmbRelTargetAttr.Items.Add(k);
                _cmbRelLookupAttr.Items.Add(k);
            }

            string savedSource = settings.LastRelationalSourceAttr ?? "Home";
            int sourceIdx = _cmbRelSourceAttr.FindStringExact(savedSource);
            _cmbRelSourceAttr.SelectedIndex = sourceIdx >= 0 ? sourceIdx : 0;

            string savedTarget = settings.LastRelationalTargetAttr ?? "Region";
            int targetIdx = _cmbRelTargetAttr.FindStringExact(savedTarget);
            _cmbRelTargetAttr.SelectedIndex = targetIdx >= 0 ? targetIdx : 0;

            string savedLookupAttr = settings.LastRelationalLookupAttr ?? "Primary";
            int lookupAttrIdx = _cmbRelLookupAttr.FindStringExact(savedLookupAttr);
            _cmbRelLookupAttr.SelectedIndex = lookupAttrIdx >= 0 ? lookupAttrIdx : 0;

            string savedHarvestAttr = settings.LastHarvestAttribute ?? "Secondary";
            int defaultHarvestIdx = _cmbHarvestAttribute.FindStringExact(savedHarvestAttr);
            _cmbHarvestAttribute.SelectedIndex = defaultHarvestIdx >= 0 ? defaultHarvestIdx : 0;
        }

        private void CmbHarvestAttribute_SelectedIndexChanged(object sender, EventArgs e)
        {
            string attr = _cmbHarvestAttribute.SelectedItem?.ToString() ?? string.Empty;
            _cmbHarvestValue.Items.Clear();
            if (string.IsNullOrWhiteSpace(attr)) return;

            var values = _catalog.GetFilterValues(attr);
            foreach (var v in values)
            {
                if (!string.IsNullOrWhiteSpace(v))
                {
                    _cmbHarvestValue.Items.Add(v);
                }
            }

            string savedHarvestVal = UserSettingsService.Current.LastHarvestValue ?? "Faction";
            int defaultIdx = _cmbHarvestValue.FindStringExact(savedHarvestVal);
            if (defaultIdx >= 0) _cmbHarvestValue.SelectedIndex = defaultIdx;
            else if (_cmbHarvestValue.Items.Count > 0) _cmbHarvestValue.SelectedIndex = 0;
        }

        private void CmbRelLookupAttr_SelectedIndexChanged(object sender, EventArgs e)
        {
            string attr = _cmbRelLookupAttr.SelectedItem?.ToString() ?? string.Empty;
            _cmbRelLookupVal.Items.Clear();
            if (string.IsNullOrWhiteSpace(attr)) return;

            var values = _catalog.GetFilterValues(attr);
            foreach (var v in values)
            {
                if (!string.IsNullOrWhiteSpace(v))
                {
                    _cmbRelLookupVal.Items.Add(v);
                }
            }

            string savedLookupVal = UserSettingsService.Current.LastRelationalLookupVal ?? "Site";
            int defaultIdx = _cmbRelLookupVal.FindStringExact(savedLookupVal);
            if (defaultIdx >= 0) _cmbRelLookupVal.SelectedIndex = defaultIdx;
            else if (_cmbRelLookupVal.Items.Count > 0) _cmbRelLookupVal.SelectedIndex = 0;
        }

        private void RuleSource_Changed(object sender, EventArgs e)
        {
            bool isHarvest = _rbHarvest.Checked;
            _cmbHarvestAttribute.Enabled = isHarvest;
            _cmbHarvestValue.Enabled = isHarvest;
            _txtHarvestCategory.Enabled = isHarvest;

            bool isRelational = _rbRelational.Checked;
            _cmbRelSourceAttr.Enabled = isRelational;
            _cmbRelLookupAttr.Enabled = isRelational;
            _cmbRelLookupVal.Enabled = isRelational;
            _cmbRelTargetAttr.Enabled = isRelational;
            _txtRelCategory.Enabled = isRelational;

            bool isQuick = _rbQuick.Checked;
            _txtRegexPattern.Enabled = isQuick;
            _txtRegexTag.Enabled = isQuick;
            _txtRegexCategory.Enabled = isQuick;

            bool isFile = _rbFile.Checked;
            _txtFilePath.Enabled = isFile;
            _btnBrowseFile.Enabled = isFile;
        }

        private void SaveCurrentSettings()
        {
            var settings = UserSettingsService.Current;

            // Mode 1 Entity Harvest
            if (_cmbHarvestAttribute.SelectedItem != null)
            {
                settings.LastHarvestAttribute = _cmbHarvestAttribute.SelectedItem.ToString();
            }
            if (_cmbHarvestValue.SelectedItem != null)
            {
                settings.LastHarvestValue = _cmbHarvestValue.SelectedItem.ToString();
            }
            if (!string.IsNullOrWhiteSpace(_txtHarvestCategory.Text))
            {
                settings.LastHarvestCategory = _txtHarvestCategory.Text.Trim();
            }

            // Mode 3 Quick Regex
            if (!string.IsNullOrWhiteSpace(_txtRegexCategory.Text))
            {
                settings.LastExtractionCategory = _txtRegexCategory.Text.Trim();
            }
            if (!string.IsNullOrWhiteSpace(_txtRegexTag.Text))
            {
                settings.LastExtractionTag = _txtRegexTag.Text.Trim();
            }
            if (!string.IsNullOrWhiteSpace(_txtRegexPattern.Text))
            {
                settings.LastExtractionPattern = _txtRegexPattern.Text.Trim();
            }

            // Mode 2 Relational Lookup
            if (!string.IsNullOrWhiteSpace(_txtRelCategory.Text))
            {
                settings.LastRelationalCategory = _txtRelCategory.Text.Trim();
            }
            if (_cmbRelSourceAttr.SelectedItem != null)
            {
                settings.LastRelationalSourceAttr = _cmbRelSourceAttr.SelectedItem.ToString();
            }
            if (_cmbRelLookupAttr.SelectedItem != null)
            {
                settings.LastRelationalLookupAttr = _cmbRelLookupAttr.SelectedItem.ToString();
            }
            if (_cmbRelLookupVal.SelectedItem != null)
            {
                settings.LastRelationalLookupVal = _cmbRelLookupVal.SelectedItem.ToString();
            }
            if (_cmbRelTargetAttr.SelectedItem != null)
            {
                settings.LastRelationalTargetAttr = _cmbRelTargetAttr.SelectedItem.ToString();
            }

            // Active mode
            if (_rbQuick.Checked) settings.LastExtractionMode = 3;
            else if (_rbRelational.Checked) settings.LastExtractionMode = 2;
            else if (_rbFile.Checked) settings.LastExtractionMode = 4;
            else settings.LastExtractionMode = 1;

            UserSettingsService.SaveSettings();
        }

        private void BtnBrowseFile_Click(object sender, EventArgs e)
        {
            using var ofd = new OpenFileDialog
            {
                Title = "Open Taxonomy Rules File",
                Filter = "JSON Rules (*.json)|*.json|All Files (*.*)|*.*"
            };

            if (ofd.ShowDialog(this) == DialogResult.OK)
            {
                try
                {
                    string json = File.ReadAllText(ofd.FileName);
                    _loadedRules = TaxonomyExtractionService.LoadRulesFromJson(json);
                    _txtFilePath.Text = ofd.FileName;
                    MessageBox.Show(this, $"Loaded {_loadedRules.Count} rule(s) successfully.", "Rules Loaded", MessageBoxButtons.OK, MessageBoxIcon.Information);
                }
                catch (Exception ex)
                {
                    MessageBox.Show(this, $"Failed to load rule file: {ex.Message}", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                }
            }
        }

        private ExtractionResult RunExtraction()
        {
            SaveCurrentSettings();

            if (_rbRelational.Checked)
            {
                string sourceAttr = _cmbRelSourceAttr.SelectedItem?.ToString() ?? "Home";
                string lookupAttr = _cmbRelLookupAttr.SelectedItem?.ToString() ?? "Primary";
                string lookupVal = _cmbRelLookupVal.SelectedItem?.ToString() ?? "Site";
                string targetAttr = _cmbRelTargetAttr.SelectedItem?.ToString() ?? "Region";
                string category = _txtRelCategory.Text.Trim();

                return TaxonomyExtractionService.ExecuteRelationalExtraction(
                    _targetCards,
                    _catalog.Cards,
                    sourceAttr,
                    lookupAttr,
                    lookupVal,
                    targetAttr,
                    category);
            }

            var rules = GetActiveRules();
            if (rules.Count == 0) return null;

            return TaxonomyExtractionService.ExecuteRules(_targetCards, rules);
        }

        private List<TaxonomyRule> GetActiveRules()
        {
            if (_rbHarvest.Checked)
            {
                string attr = _cmbHarvestAttribute.SelectedItem?.ToString() ?? string.Empty;
                string val = _cmbHarvestValue.SelectedItem?.ToString() ?? string.Empty;
                string cat = _txtHarvestCategory.Text.Trim();

                if (string.IsNullOrWhiteSpace(attr) || string.IsNullOrWhiteSpace(val)) return [];

                var harvestedNames = TaxonomyExtractionService.HarvestEntityNames(_catalog.Cards, _activeSets, attr, val);
                if (harvestedNames.Count == 0)
                {
                    MessageBox.Show(this, $"No cards in the catalog matched {attr} = '{val}' to harvest.", "Harvest Empty", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    return [];
                }

                var rule = TaxonomyExtractionService.BuildEntityHarvestRule(harvestedNames, cat);
                return rule != null ? [rule] : [];
            }

            if (_rbQuick.Checked)
            {
                return [
                    new TaxonomyRule
                    {
                        Category = _txtRegexCategory.Text.Trim(),
                        Pattern = _txtRegexPattern.Text.Trim(),
                        TagTemplate = _txtRegexTag.Text.Trim()
                    }
                ];
            }

            return _loadedRules;
        }

        private void BtnTest_Click(object sender, EventArgs e)
        {
            var result = RunExtraction();
            if (result == null)
            {
                MessageBox.Show(this, "No active rules to evaluate.", "Test Rules", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }

            _lstPreview.BeginUpdate();
            _lstPreview.Items.Clear();

            foreach (var (cardId, catDict) in result.Matches)
            {
                var card = _catalog.GetCardById(cardId);
                if (card == null) continue;

                foreach (var (cat, tags) in catDict)
                {
                    var item = new ListViewItem(card.Name);
                    item.SubItems.Add(card.Set);
                    item.SubItems.Add(cat);
                    item.SubItems.Add(string.Join("; ", tags));
                    _lstPreview.Items.Add(item);
                }
            }

            _lstPreview.EndUpdate();

            if (_lstPreview.Items.Count == 0)
            {
                MessageBox.Show(this, $"No cards in the current Master List ({_targetCards.Count} cards) matched the criteria.", "Test Preview", MessageBoxButtons.OK, MessageBoxIcon.Information);
            }
        }

        private void BtnExportCsv_Click(object sender, EventArgs e)
        {
            var result = RunExtraction();
            if (result == null || result.Matches.Count == 0)
            {
                MessageBox.Show(this, "No matching results to export.", "Export CSV", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }

            using var sfd = new SaveFileDialog
            {
                Title = "Export Extraction Draft (CSV)",
                Filter = "CSV Spreadsheet (*.csv)|*.csv",
                DefaultExt = "csv",
                FileName = "Relational_Extraction_Draft.csv"
            };

            if (sfd.ShowDialog(this) == DialogResult.OK)
            {
                TaxonomyExtractionService.ExportDraftToCsv(_targetCards, result, sfd.FileName);
                MessageBox.Show(this, $"Extraction draft exported successfully to:\n{sfd.FileName}\n\nMatched {result.Matches.Count} card(s) out of {_targetCards.Count} in scope.", "Export Successful", MessageBoxButtons.OK, MessageBoxIcon.Information);
            }
        }

        private void BtnApply_Click(object sender, EventArgs e)
        {
            var result = RunExtraction();
            if (result == null || result.Matches.Count == 0)
            {
                MessageBox.Show(this, "No matches to apply.", "Apply Tags", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }

            int cardsTagged = result.Matches.Count;
            int tagsAssigned = 0;

            foreach (var (cardId, catDict) in result.Matches)
            {
                foreach (var (category, tagSet) in catDict)
                {
                    _filterService.AddCustomKeyName(category);
                    foreach (var tag in tagSet)
                    {
                        _filterService.AppendCardCustomTag(cardId, category, tag);
                        tagsAssigned++;
                    }
                }
            }

            MessageBox.Show(this, $"Applied {tagsAssigned} tag assignment(s) across {cardsTagged} card(s) into your catalog taxonomy.", "Tags Applied", MessageBoxButtons.OK, MessageBoxIcon.Information);
            DialogResult = DialogResult.OK;
        }
    }
}

using System;
using System.IO;

namespace MECCG_Deck_Builder
{
    public static class StoragePathService
    {
        private const string AppFolderName = "MECCG Deck Builder";
        private const string PortableFlagFileName = "portable.flag";

        private static readonly Lazy<bool> s_isPortable = new(() =>
        {
            try
            {
                string portableFlag = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, PortableFlagFileName);
                return File.Exists(portableFlag);
            }
            catch
            {
                return false;
            }
        });

        /// <summary>
        /// True if portable.flag is present in the application directory.
        /// </summary>
        public static bool IsPortableMode => s_isPortable.Value;

        public static string AppBaseDirectory => AppDomain.CurrentDomain.BaseDirectory;

        /// <summary>
        /// Root storage directory: Local application directory in portable mode,
        /// or %LOCALAPPDATA%\MECCG Deck Builder\ in standard mode.
        /// </summary>
        public static string StorageRootDirectory
        {
            get
            {
                if (IsPortableMode)
                {
                    return AppBaseDirectory;
                }

                return Path.Combine(
                    Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
                    AppFolderName);
            }
        }

        public static string GetDataDirectory()
        {
            string dir = IsPortableMode
                ? AppBaseDirectory
                : Path.Combine(StorageRootDirectory, "Data");

            if (!Directory.Exists(dir))
            {
                Directory.CreateDirectory(dir);
            }
            return dir;
        }

        public static string GetImagesDirectory()
        {
            string dir = IsPortableMode
                ? Path.Combine(AppBaseDirectory, "Images")
                : Path.Combine(StorageRootDirectory, "Images");

            if (!Directory.Exists(dir))
            {
                Directory.CreateDirectory(dir);
            }
            return dir;
        }

        public static string GetSetImageDirectory(string setCode)
        {
            string cleanSet = string.IsNullOrWhiteSpace(setCode) ? "UNKNOWN" : setCode.Trim();
            string dir = Path.Combine(GetImagesDirectory(), cleanSet);
            if (!Directory.Exists(dir))
            {
                Directory.CreateDirectory(dir);
            }
            return dir;
        }

        public static string GetCardImagePath(string setCode, string imageName)
        {
            return Path.Combine(GetSetImageDirectory(setCode), imageName ?? string.Empty);
        }

        public static string GetWritableDataFilePath(string fileName)
        {
            return Path.Combine(GetDataDirectory(), fileName);
        }

        public static string GetSettingsFilePath()
        {
            if (IsPortableMode)
            {
                return Path.Combine(AppBaseDirectory, "user_settings.json");
            }

            string userDir = StorageRootDirectory;
            if (!Directory.Exists(userDir))
            {
                Directory.CreateDirectory(userDir);
            }
            return Path.Combine(userDir, "user_settings.json");
        }

        /// <summary>
        /// Resolves the path to read an existing data file.
        /// Checks user LocalAppData Data directory first, then falls back to application BaseDirectory.
        /// </summary>
        public static string ResolveDataFilePath(string fileName)
        {
            if (string.IsNullOrWhiteSpace(fileName)) return string.Empty;

            // 1. Check user data folder
            if (!IsPortableMode)
            {
                string userDataPath = Path.Combine(StorageRootDirectory, "Data", fileName);
                if (File.Exists(userDataPath))
                {
                    return userDataPath;
                }
            }

            // 2. Fall back to bundled application directory
            string appDirPath = Path.Combine(AppBaseDirectory, fileName);
            if (File.Exists(appDirPath))
            {
                return appDirPath;
            }

            // 3. Fall back to writable path for creation
            return GetWritableDataFilePath(fileName);
        }

        /// <summary>
        /// Resolves the path to read an existing card image.
        /// Checks user image cache first, then checks legacy/bundled set directories in application BaseDirectory.
        /// </summary>
        public static string ResolveImageReadPath(string setCode, string imageName)
        {
            if (string.IsNullOrWhiteSpace(imageName)) return string.Empty;

            string cleanSet = string.IsNullOrWhiteSpace(setCode) ? "UNKNOWN" : setCode.Trim();

            // 1. Check user image cache (%LOCALAPPDATA%/MECCG Deck Builder/Images/{Set}/{imageName})
            string cachePath = GetCardImagePath(cleanSet, imageName);
            if (File.Exists(cachePath))
            {
                return cachePath;
            }

            // 2. Check bundled or legacy local paths (e.g. BaseDirectory/{Set}/{imageName} or BaseDirectory/Images/{Set}/{imageName})
            string bundledLegacyPath = Path.Combine(AppBaseDirectory, cleanSet, imageName);
            if (File.Exists(bundledLegacyPath))
            {
                return bundledLegacyPath;
            }

            string bundledImagesPath = Path.Combine(AppBaseDirectory, "Images", cleanSet, imageName);
            if (File.Exists(bundledImagesPath))
            {
                return bundledImagesPath;
            }

            return cachePath;
        }
    }
}

using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;
using Newtonsoft.Json;

namespace MECCG_Deck_Builder
{
    public sealed class TaxonomyRule
    {
        public string Category { get; set; } = string.Empty;
        public string Pattern { get; set; } = string.Empty;
        public string TagTemplate { get; set; } = string.Empty;
        public string FilterPrimary { get; set; } = string.Empty;
        public string FilterSecondary { get; set; } = string.Empty;
        public string FilterSet { get; set; } = string.Empty;
    }

    public sealed class ExtractionResult
    {
        // cardId -> (Category -> Set of unique tags)
        public Dictionary<string, Dictionary<string, HashSet<string>>> Matches { get; } = new(StringComparer.OrdinalIgnoreCase);

        public void AddTag(string cardId, string category, string tag)
        {
            if (string.IsNullOrWhiteSpace(cardId) || string.IsNullOrWhiteSpace(category) || string.IsNullOrWhiteSpace(tag))
            {
                return;
            }

            if (!Matches.TryGetValue(cardId, out var catDict))
            {
                catDict = new Dictionary<string, HashSet<string>>(StringComparer.OrdinalIgnoreCase);
                Matches[cardId] = catDict;
            }

            if (!catDict.TryGetValue(category, out var tagSet))
            {
                tagSet = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                catDict[category] = tagSet;
            }

            tagSet.Add(tag.Trim());
        }

        public IReadOnlyList<string> GetAllCategories()
        {
            var categories = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (var catDict in Matches.Values)
            {
                foreach (var cat in catDict.Keys)
                {
                    categories.Add(cat);
                }
            }
            var list = categories.ToList();
            list.Sort(StringComparer.OrdinalIgnoreCase);
            return list;
        }

        public string GetFormattedTags(string cardId, string category)
        {
            if (Matches.TryGetValue(cardId, out var catDict) &&
                catDict.TryGetValue(category, out var tagSet) &&
                tagSet.Count > 0)
            {
                return string.Join("; ", tagSet.OrderBy(t => t, StringComparer.OrdinalIgnoreCase));
            }
            return string.Empty;
        }
    }

    public static class TaxonomyExtractionService
    {
        #region DYNAMIC_ENTITY_HARVESTING

        /// <summary>
        /// Queries the catalog cards for any attribute = value pair across the selected sets,
        /// returning a distinct list of harvested card titles.
        /// </summary>
        public static List<string> HarvestEntityNames(
            IEnumerable<Card> catalogCards,
            ISet<string> selectedSets,
            string attributeKey,
            string attributeValue)
        {
            if (catalogCards == null || string.IsNullOrWhiteSpace(attributeKey) || string.IsNullOrWhiteSpace(attributeValue))
            {
                return [];
            }

            return [.. catalogCards
                .Where(c => (selectedSets == null || selectedSets.Count == 0 || selectedSets.Contains(c.Set)) &&
                            string.Equals(c.GetAttribute(attributeKey), attributeValue, StringComparison.OrdinalIgnoreCase))
                .Select(c => c.Name.Trim())
                .Where(name => !string.IsNullOrEmpty(name))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .OrderBy(name => name, StringComparer.OrdinalIgnoreCase)];
        }

        /// <summary>
        /// Builds a unified Regex rule matching any of the harvested entity names using capture group $1.
        /// </summary>
        public static TaxonomyRule BuildEntityHarvestRule(IEnumerable<string> entityNames, string categoryName)
        {
            var validNames = entityNames?.Where(n => !string.IsNullOrWhiteSpace(n)).ToList() ?? [];
            if (validNames.Count == 0)
            {
                return null;
            }

            string escapedNames = string.Join("|", validNames.Select(Regex.Escape));
            string pattern = $@"(?i)\b({escapedNames})\b";

            return new TaxonomyRule
            {
                Category = string.IsNullOrWhiteSpace(categoryName) ? "Harvested Tags" : categoryName.Trim(),
                Pattern = pattern,
                TagTemplate = "$1"
            };
        }

        #endregion

        #region EXECUTION

        public static ExtractionResult ExecuteRules(IEnumerable<Card> cards, IEnumerable<TaxonomyRule> rules)
        {
            var result = new ExtractionResult();
            if (cards == null || rules == null) return result;

            var compiledRules = new List<(TaxonomyRule Rule, Regex CompiledRegex)>();
            foreach (var rule in rules)
            {
                if (string.IsNullOrWhiteSpace(rule.Pattern) || string.IsNullOrWhiteSpace(rule.Category))
                {
                    continue;
                }

                try
                {
                    var regex = new Regex(rule.Pattern, RegexOptions.IgnoreCase | RegexOptions.Compiled);
                    compiledRules.Add((rule, regex));
                }
                catch
                {
                    // Skip malformed regex gracefully
                }
            }

            foreach (var card in cards)
            {
                if (string.IsNullOrWhiteSpace(card.Text)) continue;

                // Strip flavor quotes so we only evaluate active rules text
                string rulesText = StripFlavorText(card.Text);

                foreach (var (rule, regex) in compiledRules)
                {
                    // (primary/secondary/set checks...)

                    var matches = regex.Matches(rulesText); // Use rulesText instead of card.Text
                    foreach (Match match in matches)
                    {
                        if (match.Success)
                        {
                            string tag = !string.IsNullOrWhiteSpace(rule.TagTemplate)
                                ? (rule.TagTemplate.Contains('$') ? match.Result(rule.TagTemplate) : rule.TagTemplate)
                                : match.Value;

                            result.AddTag(card.Id, rule.Category, tag);
                        }
                    }
                }
            }

            return result;
        }

        public static (int CardsTagged, int TagsAssigned) ApplyRulesDirectly(
            IEnumerable<Card> cards,
            IEnumerable<TaxonomyRule> rules,
            CardFilterService filterService)
        {
            var result = ExecuteRules(cards, rules);
            int cardsTagged = result.Matches.Count;
            int tagsAssigned = 0;

            foreach (var (cardId, catDict) in result.Matches)
            {
                foreach (var (category, tagSet) in catDict)
                {
                    filterService.AddCustomKeyName(category);
                    foreach (var tag in tagSet)
                    {
                        filterService.AppendCardCustomTag(cardId, category, tag);
                        tagsAssigned++;
                    }
                }
            }

            return (cardsTagged, tagsAssigned);
        }

        #endregion

        #region RELATIONAL_EXTRACTION

        /// <summary>
        /// Cross-references an attribute on target cards (e.g. Character 'Home') 
        /// against matching catalog entities (e.g. Site 'Name') to extract a secondary 
        /// attribute (e.g. Site 'Region') as a custom tag.
        /// </summary>
        public static ExtractionResult ExecuteRelationalExtraction(
            IEnumerable<Card> targetCards,
            IEnumerable<Card> catalogCards,
            string sourceAttribute,
            string lookupAttribute,
            string lookupValue,
            string targetAttribute,
            string categoryName)
        {
            var result = new ExtractionResult();
            if (targetCards == null || catalogCards == null ||
                string.IsNullOrWhiteSpace(sourceAttribute) || string.IsNullOrWhiteSpace(targetAttribute))
            {
                return result;
            }

            string category = string.IsNullOrWhiteSpace(categoryName) ? "Relational Tags" : categoryName.Trim();

            // 1. Build lookup dictionary from catalog entities using MatchesCardnumCriterion
            var lookupCards = catalogCards;
            if (!string.IsNullOrWhiteSpace(lookupAttribute) && !string.IsNullOrWhiteSpace(lookupValue))
            {
                lookupCards = lookupCards.Where(c => CardFilterService.MatchesCardnumCriterion(c, lookupAttribute, lookupValue));
            }

            // Map: Entity Name -> Set of extracted values (e.g. "Rivendell" -> ["Rhudaur"])
            var lookupMap = new Dictionary<string, HashSet<string>>(StringComparer.OrdinalIgnoreCase);
            foreach (var card in lookupCards)
            {
                string entityName = card.Name?.Trim();
                string targetVal = card.GetAttribute(targetAttribute)?.Trim();

                if (string.IsNullOrEmpty(entityName) || string.IsNullOrEmpty(targetVal))
                {
                    continue;
                }

                if (!lookupMap.TryGetValue(entityName, out var set))
                {
                    set = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                    lookupMap[entityName] = set;
                }
                set.Add(targetVal);
            }

            if (lookupMap.Count == 0)
            {
                return result;
            }

            var knownNames = lookupMap.Keys.OrderByDescending(k => k.Length).ToList();

            // 2. Cross-reference target cards
            foreach (var card in targetCards)
            {
                string sourceVal = card.GetAttribute(sourceAttribute);
                if (string.IsNullOrWhiteSpace(sourceVal))
                {
                    continue;
                }

                bool matched = false;

                // Split on common list delimiters (commas, semicolons, slashes)
                var parts = sourceVal.Split([',', ';', '/'], StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
                foreach (var part in parts)
                {
                    var subParts = part.Split([" or ", " and "], StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
                    foreach (var sub in subParts)
                    {
                        if (lookupMap.TryGetValue(sub, out var targets))
                        {
                            foreach (var t in targets)
                            {
                                result.AddTag(card.Id, category, t);
                                matched = true;
                            }
                        }
                    }
                }

                // If no exact token match, search known names with regex word boundaries (e.g. "Haven: Rivendell")
                if (!matched)
                {
                    foreach (var name in knownNames)
                    {
                        if (Regex.IsMatch(sourceVal, $@"\b{Regex.Escape(name)}\b", RegexOptions.IgnoreCase))
                        {
                            if (lookupMap.TryGetValue(name, out var targets))
                            {
                                foreach (var t in targets)
                                {
                                    result.AddTag(card.Id, category, t);
                                }
                            }
                        }
                    }
                }
            }

            return result;
        }

        #endregion

        #region CSV_EXPORT_AND_IMPORT

        public static void ExportTemplateDraftToCsv(
            IReadOnlyList<Card> cards,
            CardFilterService filterService,
            string filePath,
            IReadOnlyList<string> selectedAttributes = null,
            IReadOnlyList<string> selectedCategories = null)
        {
            if (cards == null || cards.Count == 0) return;

            var sb = new StringBuilder();

            // 1. Determine active official attribute columns (Slots 1 & 2)
            var attributeColumns = selectedAttributes?
                .Where(a => !string.IsNullOrWhiteSpace(a))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToList() ?? [];

            if (attributeColumns.Count == 0)
            {
                attributeColumns.Add("Primary"); // Default reference column if none selected
            }

            // 2. Determine active custom category columns (Slots 3 & 4)
            var categoryColumns = selectedCategories?
                .Where(c => !string.IsNullOrWhiteSpace(c))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToList() ?? [];

            bool hasCategoryColumns = categoryColumns.Count > 0;
            if (!hasCategoryColumns)
            {
                categoryColumns.Add("[Insert Category Name]");
            }

            // 3. Build CSV Header
            sb.Append("Card Name,Set");
            foreach (var attr in attributeColumns)
            {
                sb.Append(',').Append(EscapeCsv(attr));
            }
            foreach (var cat in categoryColumns)
            {
                sb.Append(',').Append(EscapeCsv(cat));
            }
            sb.AppendLine(",Card Text");

            // 4. Build Card Rows
            for (int i = 0; i < cards.Count; i++)
            {
                var card = cards[i];
                sb.Append(EscapeCsv(card.Name)).Append(',');
                sb.Append(EscapeCsv(card.Set));

                // Official Attributes
                foreach (var attr in attributeColumns)
                {
                    sb.Append(',').Append(EscapeCsv(card.GetAttribute(attr)));
                }

                // Custom Categories (live tags or placeholder hint)
                foreach (var cat in categoryColumns)
                {
                    if (hasCategoryColumns && filterService != null)
                    {
                        var tags = filterService.GetCardTagsForCategory(card.Id, cat);
                        string tagVal = tags.Count > 0 ? string.Join("; ", tags) : string.Empty;
                        sb.Append(',').Append(EscapeCsv(tagVal));
                    }
                    else
                    {
                        // Blank template hint on the first row
                        string hint = (i == 0) ? "[Insert tag (separate multiple tags with semicolon)]" : string.Empty;
                        sb.Append(',').Append(EscapeCsv(hint));
                    }
                }

                // Reference text
                sb.Append(',').AppendLine(EscapeCsv(card.Text));
            }

            File.WriteAllText(filePath, sb.ToString(), Encoding.UTF8);
        }

        public static void ExportDraftToCsv(
            IEnumerable<Card> cards,
            ExtractionResult result,
            string filePath,
            IEnumerable<string> categories = null)
        {
            var categoryList = categories?.ToList() ?? [.. result.GetAllCategories()];
            var sb = new StringBuilder();

            sb.Append("Card Name,Set,Primary");
            foreach (var cat in categoryList)
            {
                sb.Append(',').Append(EscapeCsv(cat));
            }
            sb.AppendLine(",Card Text");

            foreach (var card in cards.OrderBy(c => c.Name, StringComparer.Ordinal))
            {
                sb.Append(EscapeCsv(card.Name)).Append(',');
                sb.Append(EscapeCsv(card.Set)).Append(',');
                sb.Append(EscapeCsv(card.Primary));

                foreach (var cat in categoryList)
                {
                    string tags = result.GetFormattedTags(card.Id, cat);
                    sb.Append(',').Append(EscapeCsv(tags));
                }

                sb.Append(',').AppendLine(EscapeCsv(card.Text));
            }

            File.WriteAllText(filePath, sb.ToString(), Encoding.UTF8);
        }

        public static (int CardsMatched, int CategoriesImported, int TagsAssigned) ImportFromCsv(
            string filePath,
            CardCatalogService catalog,
            CardFilterService filterService)
        {
            if (!File.Exists(filePath))
            {
                throw new FileNotFoundException("The specified CSV file was not found.", filePath);
            }

            using var reader = new StreamReader(filePath, Encoding.UTF8);
            var records = ParseCsv(reader);

            if (records.Count < 2)
            {
                return (0, 0, 0);
            }

            var header = records[0];
            int nameIndex = -1;
            int setIndex = -1;
            var categoryColumnIndices = new List<(int Index, string CategoryName)>();

            // 1. Map columns from header
            for (int i = 0; i < header.Count; i++)
            {
                string col = header[i].Trim();
                if (string.Equals(col, "Card Name", StringComparison.OrdinalIgnoreCase) ||
                    string.Equals(col, "Name", StringComparison.OrdinalIgnoreCase))
                {
                    nameIndex = i;
                }
                else if (string.Equals(col, "Set", StringComparison.OrdinalIgnoreCase))
                {
                    setIndex = i;
                }
                else if (string.Equals(col, "Primary", StringComparison.OrdinalIgnoreCase) ||
                         string.Equals(col, "Card Text", StringComparison.OrdinalIgnoreCase) ||
                         string.Equals(col, "Text", StringComparison.OrdinalIgnoreCase) ||
                         string.Equals(col, "Id", StringComparison.OrdinalIgnoreCase) ||
                         CardCatalogService.FilterKeys.Contains(col, StringComparer.OrdinalIgnoreCase))
                {
                    // Skip fixed/reference columns and official database attributes
                }
                else if (!string.IsNullOrWhiteSpace(col))
                {
                    if (col.StartsWith("[Insert", StringComparison.OrdinalIgnoreCase))
                    {
                        continue; // Skip untouched template placeholder column
                    }
                    categoryColumnIndices.Add((i, col));
                }
            }

            if (nameIndex == -1 || setIndex == -1)
            {
                throw new InvalidOperationException("CSV must contain 'Card Name' and 'Set' columns.");
            }

            int cardsMatched = 0;
            int tagsAssigned = 0;
            var categoriesImportedSet = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            var matchedCardIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            // 2. Process each row with Authoritative Edit & Replace
            for (int r = 1; r < records.Count; r++)
            {
                var row = records[r];
                if (row.Count <= Math.Max(nameIndex, setIndex)) continue;

                string cardName = row[nameIndex].Trim();
                string setCode = row[setIndex].Trim();

                if (string.IsNullOrEmpty(cardName)) continue;

                var card = catalog.Cards.FirstOrDefault(c =>
                    string.Equals(c.Name, cardName, StringComparison.OrdinalIgnoreCase) &&
                    string.Equals(c.Set, setCode, StringComparison.OrdinalIgnoreCase))
                    ?? catalog.Cards.FirstOrDefault(c => string.Equals(c.Name, cardName, StringComparison.OrdinalIgnoreCase));

                if (card == null) continue;

                if (matchedCardIds.Add(card.Id))
                {
                    cardsMatched++;
                }

                // Process every custom category column present in the CSV
                foreach (var (colIdx, catName) in categoryColumnIndices)
                {
                    if (colIdx >= row.Count) continue;

                    string cellValue = row[colIdx].Trim();

                    // Skip instructional template placeholder hint if left untouched
                    if (cellValue.StartsWith("[Insert", StringComparison.OrdinalIgnoreCase))
                    {
                        continue;
                    }

                    filterService.AddCustomKeyName(catName);
                    categoriesImportedSet.Add(catName);

                    // Check for explicit clear command or empty cell
                    bool isExplicitClear = string.Equals(cellValue, "[clear]", StringComparison.OrdinalIgnoreCase) ||
                                           string.Equals(cellValue, "[none]", StringComparison.OrdinalIgnoreCase) ||
                                           string.Equals(cellValue, "-", StringComparison.Ordinal);

                    if (string.IsNullOrWhiteSpace(cellValue) || isExplicitClear)
                    {
                        // Cell was cleared: remove this category tag from the card
                        filterService.DeleteCardCustomTag(card.Id, catName);
                        continue;
                    }

                    // Parse semicolon-delimited tags
                    var tags = cellValue.Split(';', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                                        .Where(t => !t.StartsWith("[Insert", StringComparison.OrdinalIgnoreCase))
                                        .Distinct(StringComparer.OrdinalIgnoreCase)
                                        .ToList();

                    if (tags.Count > 0)
                    {
                        // Edit & Replace: overwrites existing tags for this category with the exact cell content
                        string combinedTags = string.Join("; ", tags);
                        filterService.SetCardCustomTag(card.Id, catName, combinedTags);

                        // Ensure tags are added to the dropdown value registry
                        foreach (var tag in tags)
                        {
                            filterService.AddCustomKeyValue(catName, tag);
                            tagsAssigned++;
                        }
                    }
                    else
                    {
                        filterService.DeleteCardCustomTag(card.Id, catName);
                    }
                }
            }

            return (cardsMatched, categoriesImportedSet.Count, tagsAssigned);
        }

        #endregion

        #region HELPERS_AND_PARSER

        public static string SaveRulesToJson(IEnumerable<TaxonomyRule> rules) =>
            JsonConvert.SerializeObject(rules, Formatting.Indented);

        public static List<TaxonomyRule> LoadRulesFromJson(string json) =>
            JsonConvert.DeserializeObject<List<TaxonomyRule>>(json) ?? [];

        private static string EscapeCsv(string field)
        {
            if (string.IsNullOrEmpty(field)) return string.Empty;
            if (field.Contains(',') || field.Contains('"') || field.Contains('\r') || field.Contains('\n'))
            {
                return $"\"{field.Replace("\"", "\"\"")}\"";
            }
            return field;
        }

        public static List<List<string>> ParseCsv(TextReader reader)
        {
            var records = new List<List<string>>();
            var currentRecord = new List<string>();
            var currentField = new StringBuilder();
            bool inQuotes = false;
            int nextChar;

            while ((nextChar = reader.Read()) != -1)
            {
                char c = (char)nextChar;

                if (inQuotes)
                {
                    if (c == '"')
                    {
                        if (reader.Peek() == '"')
                        {
                            reader.Read();
                            currentField.Append('"');
                        }
                        else
                        {
                            inQuotes = false;
                        }
                    }
                    else
                    {
                        currentField.Append(c);
                    }
                }
                else
                {
                    if (c == '"')
                    {
                        inQuotes = true;
                    }
                    else if (c == ',')
                    {
                        currentRecord.Add(currentField.ToString());
                        currentField.Clear();
                    }
                    else if (c == '\r')
                    {
                        if (reader.Peek() == '\n')
                        {
                            reader.Read();
                        }
                        currentRecord.Add(currentField.ToString());
                        currentField.Clear();
                        records.Add(currentRecord);
                        currentRecord = [];
                    }
                    else if (c == '\n')
                    {
                        currentRecord.Add(currentField.ToString());
                        currentField.Clear();
                        records.Add(currentRecord);
                        currentRecord = [];
                    }
                    else
                    {
                        currentField.Append(c);
                    }
                }
            }

            if (currentField.Length > 0 || currentRecord.Count > 0)
            {
                currentRecord.Add(currentField.ToString());
                records.Add(currentRecord);
            }

            return records;
        }

#pragma warning disable SYSLIB1045 // Use 'GeneratedRegexAttribute'
        private static readonly Regex FlavorQuotesRegex = new(@"[""“\u201C][^""”\u201D]*[""”\u201D]", RegexOptions.Compiled);
        private static readonly Regex FlavorAttributionRegex = new(
    @"[—–-]\s*(?:LotR|Hobbit|The Hobbit|Silmarillion)(?:\s+[IVX0-9]+)?(?:\s*,\s*[^.\r\n]+)?(?=\s+Home Site:|$)",
    RegexOptions.Compiled | RegexOptions.IgnoreCase);
#pragma warning restore SYSLIB1045

        /// <summary>
        /// Strips Tolkien flavor quotes ("..." or “...”) and book attributions (—LotR) 
        /// so entity harvesting only matches functional gameplay rules text.
        /// </summary>
        public static string StripFlavorText(string text)
        {
            if (string.IsNullOrWhiteSpace(text)) return string.Empty;

            // Remove everything between quotation marks ("..." or “...”)
            string cleaned = FlavorQuotesRegex.Replace(text, " ");

            // Remove trailing book citations like —LotRIV or —Hobbit
            cleaned = FlavorAttributionRegex.Replace(cleaned, " ");

            return cleaned.Trim();
        }

        #endregion
    }
}

using System;
using System.Collections.Generic;
using System.IO;
using Newtonsoft.Json;

namespace MECCG_Deck_Builder
{
    public sealed class UserSettings
    {
        public List<string> SelectedSets { get; set; } = [];

        // Active mode
        public int LastExtractionMode { get; set; } = 1; // 1 = Harvest, 2 = Relational, 3 = Quick Regex, 4 = File

        // Mode 1 Entity Harvest Defaults
        public string LastHarvestAttribute { get; set; } = "Secondary";
        public string LastHarvestValue { get; set; } = "Faction";
        public string LastHarvestCategory { get; set; } = "Faction Focus";

        // Mode 2 Relational Defaults
        public string LastRelationalCategory { get; set; } = "Home Region";
        public string LastRelationalSourceAttr { get; set; } = "Home";
        public string LastRelationalLookupAttr { get; set; } = "Primary";
        public string LastRelationalLookupVal { get; set; } = "Site";
        public string LastRelationalTargetAttr { get; set; } = "Region";

        // Mode 3 Regex Defaults
        public string LastExtractionCategory { get; set; } = "Custom Trait";
        public string LastExtractionTag { get; set; } = "$1";
        public string LastExtractionPattern { get; set; } = @"(?i)Dwarf factions?";
    }

    public static class UserSettingsService
    {
        private static UserSettings s_current;

        public static UserSettings Current
        {
            get
            {
                s_current ??= LoadSettings();
                return s_current;
            }
        }

        public static UserSettings LoadSettings()
        {
            try
            {
                string path = StoragePathService.GetSettingsFilePath();
                if (File.Exists(path))
                {
                    string json = File.ReadAllText(path);
                    var settings = JsonConvert.DeserializeObject<UserSettings>(json);
                    if (settings != null)
                    {
                        return settings;
                    }
                }
                else if (!StoragePathService.IsPortableMode)
                {
                    // Check legacy path in app directory for seamless migration
                    string legacyPath = Path.Combine(StoragePathService.AppBaseDirectory, "user_settings.json");
                    if (File.Exists(legacyPath))
                    {
                        string json = File.ReadAllText(legacyPath);
                        var settings = JsonConvert.DeserializeObject<UserSettings>(json);
                        if (settings != null)
                        {
                            s_current = settings; // Assign BEFORE saving to prevent recursion
                            SaveSettings();
                            return settings;
                        }
                    }
                }
            }
            catch
            {
                // Graceful fallback to default instance on I/O or JSON read errors
            }

            return new UserSettings();
        }

        public static void SaveSettings()
        {
            // Access s_current directly to avoid re-triggering LoadSettings()
            var settingsToSave = s_current;
            if (settingsToSave == null) return;

            try
            {
                string path = StoragePathService.GetSettingsFilePath();
                string json = JsonConvert.SerializeObject(settingsToSave, Formatting.Indented);
                File.WriteAllText(path, json);
            }
            catch
            {
                // Non-fatal if disk write fails due to permissions
            }
        }
    }
}
